solution:
def longest_balanced(bits: list[int]) -> int:
    first_seen = {0: -1}                 # a total of 0 exists before the first bit
    total = best = 0
    for i, bit in enumerate(bits):
        total += 1 if bit else -1
        if total in first_seen:
            best = max(best, i - first_seen[total])
        else:
            first_seen[total] = i        # keep only the earliest index
    return best

perf.naive:
def longest_balanced(bits: list[int]) -> int:
    best = 0
    for i in range(len(bits)):
        total = 0
        for j in range(i, len(bits)):
            total += 1 if bits[j] else -1
            if total == 0:
                best = max(best, j - i + 1)
    return best
